> 💡 **Пример: f-string**

**Что делает:** Форматированные строки с интерполяцией {expr}

**Зачем нужно:** Быстрее и читаемее .format() и %, поддерживает любые выражения внутри {}

**Как работает:** f'Привет, {name}! Тебе {age} лет.' вместо 'Привет, ' + name + '! Тебе ' + str(age) + ' лет.'

class Counter:
    def __init__(self):
        self.value = 0

    def increment(self):
        self.value += 1
        return self  # для цепочек вызовов

c = Counter()
c.increment().increment().increment()
print(c.value)  # 3

> 💡 **Пример: f-string**

**Что делает:** Форматированные строки с интерполяцией {expr}

**Зачем нужно:** Быстрее и читаемее .format() и %, поддерживает любые выражения внутри {}

**Как работает:** f'Привет, {name}! Тебе {age} лет.' вместо 'Привет, ' + name + '! Тебе ' + str(age) + ' лет.'

class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    # Строковое представление
    def __str__(self):
        return f"({self.x}, {self.y})"

    def __repr__(self):
        return f"Vector({self.x}, {self.y})"

    # Сравнение
    def __eq__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        return self.x == other.x and self.y == other.y

    # Арифметика
    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def __mul__(self, scalar):
        return Vector(self.x * scalar, self.y * scalar)

    # Индексация
    def __getitem__(self, index):
        if index == 0:
            return self.x
        elif index == 1:
            return self.y
        raise IndexError("Vector has only 2 components")

    def __len__(self):
        return 2

    # Контекстный менеджер
    def __enter__(self):
        print("Вход в контекст")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        print("Выход из контекста")


v1 = Vector(1, 2)
v2 = Vector(3, 4)
v3 = v1 + v2          # Vector(4, 6)
v4 = v1 * 3           # Vector(3, 6)
print(v1)             # (1, 2)
print(v1[0])          # 1
print(len(v1))        # 2
print(v1 == Vector(1, 2))  # True

